#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAXN 20
#define MAXLEN 100

int n;
char strings[MAXN][MAXLEN];
// memo[mask][last_char] = bitmask of terminal chars (26 bits)
// -1 means not computed
int memo[1<<MAXN][26];
int computed[1<<MAXN][26];

int dfs(int mask, int last_char) {
    if (computed[mask][last_char]) return memo[mask][last_char];
    computed[mask][last_char] = 1;

    int result = 0;
    int found = 0;

    for (int i = 0; i < n; i++) {
        if (mask & (1<<i)) continue;
        if (strings[i][0] - 'a' != last_char) continue;
        found = 1;
        int new_last = strings[i][strlen(strings[i])-1] - 'a';
        result |= dfs(mask | (1<<i), new_last);
    }

    if (!found) {
        result = (1 << last_char);
    }

    memo[mask][last_char] = result;
    return result;
}

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%s", strings[i]);

    memset(computed, 0, sizeof(computed));

    int answer = 0;
    for (int i = 0; i < n; i++) {
        int last = strings[i][strlen(strings[i])-1] - 'a';
        answer |= dfs(1<<i, last);
    }

    for (int c = 0; c < 26; c++) {
        if (answer & (1<<c)) printf("%c\n", 'a'+c);
    }

    return 0;
}

