typedef struct {
    int to;
    int next;
} Edge;

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *indeg = (int *)calloc(26, sizeof(int));
    int *outdeg = (int *)calloc(26, sizeof(int));

    Edge *edges = (Edge *)malloc(sizeof(Edge) * n);
    int *head = (int *)malloc(sizeof(int) * 26);
    for (int i = 0; i < 26; i++) head[i] = -1;

    int edgeCnt = 0;
    int usedVertex[26] = {0};

    char s[1000005];
    for (int i = 0; i < n; i++) {
        scanf("%s", s);
        int len = (int)strlen(s);
        int u = s[0] - 'a';
        int v = s[len - 1] - 'a';

        outdeg[u]++;
        indeg[v]++;
        usedVertex[u] = usedVertex[v] = 1;

        edges[edgeCnt].to = v;
        edges[edgeCnt].next = head[u];
        head[u] = edgeCnt++;
    }

    int plus1 = 0, minus1 = 0;
    int possibleEnd[26] = {0};

    for (int i = 0; i < 26; i++) {
        int diff = outdeg[i] - indeg[i];
        if (diff == 1) plus1++;
        else if (diff == -1) minus1++;
        else if (diff != 0) {
            // No Euler trail/circuit using all strings
            for (int c = 0; c < 26; c++) free(NULL);
            free(indeg);
            free(outdeg);
            free(edges);
            free(head);
            return 0;
        }
    }

    if (plus1 == 0 && minus1 == 0) {
        for (int i = 0; i < 26; i++) {
            if (outdeg[i] > 0) possibleEnd[i] = 1;
        }
    } else if (plus1 == 1 && minus1 == 1) {
        for (int i = 0; i < 26; i++) {
            if (indeg[i] - outdeg[i] == 1) {
                possibleEnd[i] = 1;
                break;
            }
        }
    }

    int first = 1;
    for (int i = 0; i < 26; i++) {
        if (possibleEnd[i]) {
            if (!first) printf(" ");
            printf("%c", 'a' + i);
            first = 0;
        }
    }
    printf("\n");

    free(indeg);
    free(outdeg);
    free(edges);
    free(head);
    return 0;
}

