int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> inDeg(26, 0), outDeg(26, 0);
    vector<vector<int>> g(26), rg(26);
    vector<bool> used(26, false);

    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;
        int u = s.front() - 'a';
        int v = s.back() - 'a';
        outDeg[u]++;
        inDeg[v]++;
        g[u].push_back(v);
        rg[v].push_back(u);
        used[u] = used[v] = true;
    }

    // Check weak connectivity among used vertices
    int start = -1;
    for (int i = 0; i < 26; ++i) {
        if (used[i]) {
            start = i;
            break;
        }
    }

    if (start == -1) {
        // No strings; no final character exists
        cout << "\n";
        return 0;
    }

    vector<bool> vis(26, false);
    queue<int> q;
    q.push(start);
    vis[start] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : g[u]) {
            if (!vis[v]) {
                vis[v] = true;
                q.push(v);
            }
        }
        for (int v : rg[u]) {
            if (!vis[v]) {
                vis[v] = true;
                q.push(v);
            }
        }
    }

    for (int i = 0; i < 26; ++i) {
        if (used[i] && !vis[i]) {
            cout << "\n";
            return 0;
        }
    }

    vector<char> ans;

    for (int t = 0; t < 26; ++t) {
        if (!used[t]) continue;

        int plus1 = 0, minus1 = 0;
        bool ok = true;

        for (int i = 0; i < 26; ++i) {
            int diff = outDeg[i] - inDeg[i];
            if (i == t) diff += 1; // pretend one extra incoming edge to t

            if (diff == 1) plus1++;
            else if (diff == -1) minus1++;
            else if (diff != 0) {
                ok = false;
                break;
            }
        }

        // Existence of Euler trail ending at t:
        // after adding imaginary edge t -> start? Equivalent degree condition:
        // exactly one +1 and one -1, or all zero (Euler circuit).
        if (ok && ((plus1 == 1 && minus1 == 1) || (plus1 == 0 && minus1 == 0))) {
            ans.push_back(char('a' + t));
        }
    }

    for (char c : ans) cout << c;
    cout << '\n';
    return 0;
}

