public class Shiritori {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.nextLine();
        List<String> words = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            words.add(sc.nextLine().trim());
        }

        Set<Character> possibleLastChars = new HashSet<>();
        boolean[] used = new boolean[n];

        for (int i = 0; i < n; i++) {
            used[i] = true;
            dfs(words.get(i), words, used, possibleLastChars);
            used[i] = false;
        }

        List<Character> result = new ArrayList<>(possibleLastChars);
        Collections.sort(result);
        for (char c : result) {
            System.out.println(c);
        }
    }

    private static void dfs(String current, List<String> words, boolean[] used, Set<Character> possibleLastChars) {
        char lastChar = current.charAt(current.length() - 1);
        boolean moved = false;
        for (int i = 0; i < words.size(); i++) {
            if (!used[i] && words.get(i).charAt(0) == lastChar) {
                used[i] = true;
                dfs(words.get(i), words, used, possibleLastChars);
                used[i] = false;
                moved = true;
            }
        }
        if (!moved) {
            possibleLastChars.add(lastChar);
        }
    }
}

