public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        int[][] cnt = new int[26][26];
        int[] in = new int[26];
        int[] out = new int[26];
        boolean[] used = new boolean[26];

        for (int i = 0; i < n; i++) {
            String s = fs.next();
            int a = s.charAt(0) - 'a';
            int b = s.charAt(s.length() - 1) - 'a';
            cnt[a][b]++;
            out[a]++;
            in[b]++;
            used[a] = true;
            used[b] = true;
        }

        StringBuilder ans = new StringBuilder();

        for (int end = 0; end < 26; end++) {
            if (!used[end]) continue;

            int plus1 = 0, minus1 = 0;
            boolean ok = true;

            for (int v = 0; v < 26; v++) {
                int diff = out[v] - in[v];
                if (v == end) diff += 1; // after removing trail ending at 'end', remaining graph must be balanced except start
                if (diff == 1) plus1++;
                else if (diff == -1) minus1++;
                else if (diff != 0) {
                    ok = false;
                    break;
                }
            }

            if (!ok) continue;
            if (!(plus1 == 1 && minus1 == 1) && !(plus1 == 0 && minus1 == 0)) continue;

            if (!isConnectedIgnoringDirection(cnt, in, out, end)) continue;

            ans.append((char) ('a' + end));
        }

        System.out.println(ans.toString());
    }

    static boolean isConnectedIgnoringDirection(int[][] cnt, int[] in, int[] out, int end) {
        boolean[] present = new boolean[26];
        int total = 0;
        for (int i = 0; i < 26; i++) {
            if (in[i] + out[i] > 0) {
                present[i] = true;
                total++;
            }
        }
        if (total == 0) return false;

        int start = -1;
        for (int i = 0; i < 26; i++) {
            if (present[i] && i != end) {
                start = i;
                break;
            }
        }
        if (start == -1) {
            // only possible used vertex is 'end'
            // valid iff there is at least one loop on end
            return cnt[end][end] > 0;
        }

        boolean[] vis = new boolean[26];
        ArrayDeque<Integer> q = new ArrayDeque<>();
        vis[start] = true;
        q.add(start);

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v = 0; v < 26; v++) {
                if (u == end || v == end) {
                    // remove exactly one trail ending at end, but connectivity condition
                    // is checked on the original underlying graph; this is sufficient
                    // because Euler trail existence conditions plus connectedness are enough.
                }
                if (!vis[v] && (cnt[u][v] > 0 || cnt[v][u] > 0)) {
                    vis[v] = true;
                    q.add(v);
                }
            }
        }

        for (int i = 0; i < 26; i++) {
            if (present[i] && !vis[i]) return false;
        }
        return true;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

